SELECT (SELECT name FROM warehouses w WHERE w.warehouse_id = s.warehouse_id), COUNT(*) FILTER (WHERE on_hand_units = 0) * 1.0 / COUNT(*) FROM inventory_snapshots s WHERE s.warehouse_id IN (SELECT warehouse_id FROM warehouses WHERE name LIKE 'Gazipur-%') AND s.snapshot_date >= DATE '2024-01-01' AND s.snapshot_date <= DATE '2024-12-31' GROUP BY s.warehouse_id
